draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // draw apple
  ctx.fillStyle = 'red';
  ctx.beginPath();
  ctx.arc(W/2 + Math.sin(t)*50, H/2, 30, 0, 2*Math.PI);
  ctx.fill();
  ctx.stroke();

  // draw banana
  ctx.fillStyle = 'yellow';
  ctx.beginPath();
  ctx.arc(W/2 + 100 + Math.cos(t)*20, H/2 + 50, 20, 0, 2*Math.PI);
  ctx.fill();
  ctx.stroke();
  ctx.beginPath();
  ctx.rect(W/2 + 90 + Math.cos(t)*20, H/2 + 30, 40, 60);
  ctx.fill();
  ctx.stroke();

  // draw stick figure
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2 - 100, H/2 - 50, 20, 0, 2*Math.PI);
  ctx.fill();
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 100, H/2 - 30);
  ctx.lineTo(W/2 - 100, H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 100, H/2);
  ctx.lineTo(W/2 - 150, H/2 + 20);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 100, H/2);
  ctx.lineTo(W/2 - 50, H/2 + 20);
  ctx.stroke();

  ctx.restore();
}
